{"script":"function searchNewReleases() {
  // Get all text content from the page using XPath
  const xpath = "//*[contains(translate(text(), 'NEW RELEASE', 'new release'), 'new release')]";
  const result = document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
  const matches = [];

  for (let i = 0; i < result.snapshotLength; i++) {
    const node = result.snapshotItem(i);
    matches.push({
      tag: node.tagName,
      text: node.textContent.trim().substring(0, 200),
      className: node.className
    });
  }

  // Also check data attributes
  const dataAttrs = document.querySelectorAll('[data-testid*="release"], [data-testid*="new"]');
  const dataInfo = [];
  dataAttrs.forEach(el => {
    dataInfo.push(el.tagName + ': ' + (el.dataset.testid || '') + ' - ' + el.textContent.trim().substring(0, 100));
  });

  return {
    matches: matches,
    dataAttributes: dataInfo,
    bodyHasNewReleases: document.body.innerText.toLowerCase().includes('new release')
  };
}
return JSON.stringify(searchNewReleases(), null, 2);"}

