{"script":"function searchNewReleases() {
  // Get all text content from the page
  const pageText = document.body.innerText;

  // Search for various forms of "New Releases"
  const searchTerms = ['New Releases', 'New Release', 'New releases', 'new releases'];
  const results = [];

  searchTerms.forEach(term => {
    if (pageText.includes(term)) {
      results.push(`Found: "${term}"`);
      // Find the surrounding context
      const idx = pageText.indexOf(term);
      const context = pageText.substring(Math.max(0, idx - 100), Math.min(pageText.length, idx + 300));
      results.push(`Context: ${context}`);
    }
  });

  // Also search headings specifically
  const headings = document.querySelectorAll('h1, h2, h3, h4, span[data-testid*="title"]');
  headings.forEach(heading => {
    if (heading.textContent.toLowerCase().includes('new release')) {
      results.push(`Heading: ${heading.textContent} - Parent: ${heading.parentElement.outerHTML.substring(0, 500)}`);
    }
  });

  return results.length > 0 ? results.join('\n---\n') : 'No "New Releases" section found on page';
}"}

