{"script":"function thoroughSearch() {
  // Check all elements including hidden ones
  const allElements = document.querySelectorAll('*');
  const matches = [];

  for (let el of allElements) {
    const text = el.textContent || '';
    if (text.toLowerCase().includes('new release') && el.children.length === 0) {
      matches.push({
        tag: el.tagName,
        text: text.trim().substring(0, 200),
        parent: el.parentElement?.textContent?.trim().substring(0, 300) || ''
      });
    }
  }

  // Check for section titles
  const sections = document.querySelectorAll('[data-testid="section-title-wrapper"], h1, h2, h3');
  const sectionTitles = [];
  sections.forEach(s => {
    if (s.textContent.trim()) {
      sectionTitles.push(s.textContent.trim());
    }
  });

  return {
    matches: matches.slice(0, 10),
    sectionTitles: sectionTitles,
    currentURL: window.location.href
  };
}
return JSON.stringify(thoroughSearch(), null, 2);"}

