{"script":"function thoroughSearch() {
  // Get all section labels/titles
  const allSectionTitles = [];
  const elements = document.querySelectorAll('[data-testid="section-title-wrapper"] *');
  elements.forEach(el => {
    const text = el.textContent.trim();
    if (text && !allSectionTitles.includes(text)) {
      allSectionTitles.push(text);
    }
  });

  // Also check for any links or buttons that mention new releases
  const linksAndButtons = document.querySelectorAll('a, button');
  const newReleaseRefs = [];
  linksAndButtons.forEach(el => {
    if (el.textContent.toLowerCase().includes('new release') || 
        (el.getAttribute('aria-label') || '').toLowerCase().includes('new release') ||
        (el.getAttribute('href') || '').toLowerCase().includes('new-release')) {
      newReleaseRefs.push({
        tag: el.tagName,
        text: el.textContent.trim().substring(0, 100),
        href: el.getAttribute('href') || '',
        ariaLabel: el.getAttribute('aria-label') || ''
      });
    }
  });

  // Check all data-testid attributes
  const allDataTestids = [];
  document.querySelectorAll('[data-testid]').forEach(el => {
    const tid = el.getAttribute('data-testid') || '';
    if (tid.includes('release') || tid.includes('new')) {
      allDataTestids.push(tid + ': ' + el.textContent.trim().substring(0, 50));
    }
  });

  return {
    sectionTitles: allSectionTitles,
    newReleaseRefs: newReleaseRefs,
    newTestids: allDataTestids
  };
}
return JSON.stringify(thoroughSearch(), null, 2);"}

