function searchNewReleases() {
  // Get all text content from the page
  const pageText = document.body.innerText;

  // Search for various forms of "New Releases"
  const searchTerms = ['New Releases', 'New Release', 'New releases', 'new releases'];
  const results = [];

  searchTerms.forEach(term => {
    if (pageText.includes(term)) {
      results.push('Found: "' + term + '"');
      // Find the surrounding context
      const idx = pageText.indexOf(term);
      const context = pageText.substring(Math.max(0, idx - 200), Math.min(pageText.length, idx + 500));
      results.push('Context: ' + context);
    }
  });

  // Also list all section titles to find what's there
  const sections = document.querySelectorAll('h2, h3, [data-testid="section-title-wrapper"]');
  const sectionTitles = [];
  sections.forEach(s => {
    if (s.textContent.trim()) {
      sectionTitles.push(s.textContent.trim());
    }
  });

  return results.length > 0 ? results.join('\n---\n') : 'No "New Releases" found. Sections: ' + sectionTitles.join(', ');
}
return searchNewReleases();

